/* part:page.script.preview.kit.split-pane */
/* The catalog's live preview of kit.split-pane. It rides with the kit and only the catalog page loads it: `adp.py take` leaves it out. */
(function () {
'use strict';
const { html, useState, useEffect, useRef } = window.htmPreact;
const P = window.CatalogPreviews = window.CatalogPreviews || {};
const K = () => window.Kit;
const first = (samples, part) => samples[Object.keys(samples).find(k => k.endsWith('/' + part + '.json'))];
const Sim = ({ children }) => html`<p class="pv-sim"><b>Sandbox</b> ${children}</p>`;
const Cases = ({ d, value, set, label = 'Use case' }) => html`<div class="pv-row" role="group" aria-label=${label}><span class="pv-label">${label}</span>
  ${d.cases.map(c => html`<button type="button" key=${c.id} class=${'pv-btn' + (c.id === value ? ' pri' : '')} aria-pressed=${c.id === value} onClick=${() => set(c.id)}>${c.label}</button>`)}</div>`;

const node = (tag, text, cls) => { const n = document.createElement(tag); if (text != null) n.textContent = text; if (cls) n.className = cls; return n; };
// a pane spec is {title, list | text | code} or {split: opts-with-a-and-b}: nested splits are mounted in the pane
function fill(pane, spec, out) {
  if (spec.split) { out.push(build(pane, spec.split)); return; }
  pane.style.padding = '12px 14px';
  pane.append(node('h4', spec.title, 'pv-pane-h'));
  if (spec.code) pane.append(node('pre', spec.code, 'pv-pane-code'));
  (spec.text || []).forEach(t => pane.append(node('p', t, 'pv-pane-p')));
  if (spec.list) { const ul = node('ul', null, 'pv-pane-ul'); spec.list.forEach(t => ul.append(node('li', t))); pane.append(ul); }
}
function build(host, o, onChange) {
  const sp = K().splitPane.mount(host, { orientation: o.orientation, size: o.size, min: o.min, max: o.max, collapse: o.collapse, key: o.key, label: o.label, height: '100%', onChange });
  const kids = [];
  fill(sp.a, o.a, kids); fill(sp.b, o.b, kids);
  const destroy = sp.destroy; sp.destroy = () => { kids.forEach(k => k.destroy()); destroy(); };
  return sp;
}
const CSS = `.pv-pane-h{margin:0 0 8px;font:600 13px/1.3 var(--f-ui)}.pv-pane-p{margin:0 0 8px;font:13px/1.5 var(--f-ui);color:var(--ink-2)}
.pv-pane-ul{margin:0;padding:0;list-style:none;display:grid;gap:2px;font:13px/1.4 var(--f-ui)}.pv-pane-ul li{padding:5px 8px;border-radius:5px;background:var(--sunk)}
.pv-pane-code{margin:0;padding:8px 10px;border-radius:6px;background:var(--sunk);font:12px/1.5 var(--f-mono);overflow:auto;white-space:pre}
.pv-sp-box{height:340px;border:1px solid var(--rule);border-radius:8px;background:var(--panel);color:var(--ink);overflow:hidden}`;

P['kit.split-pane'] = ({ samples }) => {
  const d = first(samples, 'split-pane');
  const [id, setId] = useState(d.cases[0].id);
  const c = d.cases.find(x => x.id === id);
  const host = useRef(null), sp = useRef(null);
  const [st, setSt] = useState(null);
  useEffect(() => {
    const onChange = s => setSt(s);
    sp.current = build(host.current, c.split, onChange);
    setSt({ size: sp.current.size(), collapsed: sp.current.collapsed() });
    return () => { sp.current.destroy(); sp.current = null; };
  }, [id]);
  const o = c.split;
  const sides = o.orientation === 'vertical' ? ['top', 'bottom'] : ['left', 'right'];
  const can = k => o.collapse === 'both' || o.collapse === k || !o.collapse;
  return html`<div class="pv-stack"><style>${CSS}</style>
    <${Cases} d=${d} value=${id} set=${setId}/>
    <${Sim}>${c.context} The page gives each pane its content; the kit only draws the divider and keeps the size${o.key ? ' (remembered in this browser)' : ''}.<//>
    <div class="pv-row"><span class="pv-label" aria-live="polite">${st ? `first pane ${st.size}%${st.collapsed ? ', ' + (st.collapsed === 'a' ? sides[0] : sides[1]) + ' collapsed' : ''}` : ''}</span>
      ${['a', 'b'].map((k, i) => can(k) && html`<button type="button" key=${k} class="pv-btn" onClick=${() => sp.current && sp.current.collapse(k)}>Collapse ${sides[i]}</button>`)}
      <button type="button" class="pv-btn" onClick=${() => sp.current && sp.current.restore()}>Restore</button>
      <span class="pv-label">Tab to the divider: arrows, Home, End, Enter; double-click resets</span></div>
    <div class="pv-sp-box"><div ref=${host} style="height:100%"></div></div>
  </div>`;
};
})();
/* /part:page.script.preview.kit.split-pane */

