/* part:page.style.kit.split-pane */
/* Kit css: Split pane    kit version 0.1.0    pairs with kit/split-pane.js
   .kit-sp (.kit-sp-h side by side, .kit-sp-v stacked) > .kit-sp-pane + .kit-sp-bar (the divider, with .kit-sp-grip) + .kit-sp-pane. The script sets the grid tracks, in fr, so the ratio survives a resize.
   The divider is a 10px track with a 24px hit area (it overlaps 7px of each pane); the panes keep their own padding and background (a collapsed pane drops them). --kit-sp-h sets the height, --kit-sp-d the divider track.
   Needs from the board: --panel --rule --ink-3 --accent, optional --seam --radius */
.kit-sp { display: grid; width: 100%; height: var(--kit-sp-h, 100%); min-width: 0; min-height: 0; }
.kit-sp-h { grid-auto-rows: minmax(0, 1fr); }
.kit-sp-v { grid-template-columns: minmax(0, 1fr); }
.kit-sp-pane { min-width: 0; min-height: 0; overflow: auto; }
.kit-sp-pane[inert] { overflow: hidden; padding: 0 !important; border-width: 0 !important; }   /* a collapsed pane is nothing, whatever padding or border the page gave it */
.kit-sp-bar { position: relative; z-index: 1; touch-action: none; user-select: none; -webkit-user-select: none; outline: none; }
.kit-sp-h > .kit-sp-bar { width: var(--kit-sp-d, 10px); cursor: col-resize; }
.kit-sp-v > .kit-sp-bar { height: var(--kit-sp-d, 10px); cursor: row-resize; }
.kit-sp-bar::before { content: ""; position: absolute; }
.kit-sp-h > .kit-sp-bar::before { inset: 0 -7px; }
.kit-sp-v > .kit-sp-bar::before { inset: -7px 0; }
/* collapsed: the divider sits on the host's edge, which may clip, so the 24px hit area grows only toward the open pane */
.kit-sp-h > .kit-sp-bar[data-c=a]::before { inset: 0; inset-inline-end: -14px; }
.kit-sp-h > .kit-sp-bar[data-c=b]::before { inset: 0; inset-inline-start: -14px; }
.kit-sp-v > .kit-sp-bar[data-c=a]::before { inset: 0 0 -14px; }
.kit-sp-v > .kit-sp-bar[data-c=b]::before { inset: -14px 0 0; }
.kit-sp-bar::after { content: ""; position: absolute; background: var(--rule); }
.kit-sp-h > .kit-sp-bar::after { top: 0; bottom: 0; left: calc(50% - 1px); width: 2px; }
.kit-sp-v > .kit-sp-bar::after { left: 0; right: 0; top: calc(50% - 1px); height: 2px; }
.kit-sp-grip { position: absolute; z-index: 1; border-radius: 3px; background: var(--ink-3); box-shadow: 0 0 0 2px var(--panel); pointer-events: none; }
.kit-sp-h > .kit-sp-bar > .kit-sp-grip { left: 3px; right: 3px; top: calc(50% - 16px); height: 32px; }
.kit-sp-v > .kit-sp-bar > .kit-sp-grip { top: 3px; bottom: 3px; left: calc(50% - 16px); width: 32px; }
.kit-sp-bar:hover::after, .kit-sp-drag > .kit-sp-bar::after { background: var(--accent); }
.kit-sp-bar:hover > .kit-sp-grip, .kit-sp-drag > .kit-sp-bar > .kit-sp-grip { background: var(--accent); }
.kit-sp-bar:focus-visible { outline: 2px solid var(--seam, var(--accent)); outline-offset: 1px; border-radius: var(--radius, 4px); }
.kit-sp-drag { user-select: none; -webkit-user-select: none; }
@media (prefers-reduced-motion: no-preference) { .kit-sp:not(.kit-sp-drag) { transition: grid-template-columns .16s ease, grid-template-rows .16s ease; } }
/* /part:page.style.kit.split-pane */

/**
 * Split pane
 * Kit.splitPane.mount(el, opts) fills el with two panes and a draggable divider between them, side by side or stacked. The divider is the WAI-ARIA window splitter: role=separator with aria-valuenow, arrow keys, Home and End, Enter to collapse and restore. Pointer, touch and pen drag it. Sizes are percentages of the room the panes share, so resizing the window keeps the ratio; a pane's min and max can be percent or px. A pane can collapse to nothing and come back to where it was, and the size can be remembered in this browser.
 *
 * What it is: the one resizable divider for a page's two-part layouts (list and detail, editor and results, tree and everything else). It does not lay out what is inside the panes: put content in pane.a and pane.b, or mount another split pane in one of them to get three or more parts.
 * Leaves out (the page does it): more than two panes by itself (nest them), the content and its overflow rules, the host's height when stacked, and sharing a size between viewers or devices (the memory is localStorage of one browser).
 * API (small and stable):
 *   Kit.splitPane.mount(el, {a, b, orientation, size, min, max, collapse, step, key, label, height, onChange}) -> split
 *     a, b          nodes or text put in the first and second pane (or fill split.a and split.b yourself)
 *     orientation   "horizontal" (default): panes side by side, divider vertical; "vertical": panes stacked, divider horizontal
 *     size          size of the first pane in percent, the default (default 50); a double click on the divider returns to it
 *     min, max      limits per pane: a number or "30%" (percent), "240px", or [first, second]; min default 10 (percent), max default 100. max is the pane's own largest size
 *     collapse      which pane may collapse to nothing: "both" (default), "a", "b" or "none". Dragging past half of a min collapses; so does an arrow key pressed at the min
 *     step          arrow key step in percent (default 5)
 *     key           localStorage key that remembers the size and the collapse per viewer; no key, nothing is remembered
 *     label         accessible name of the divider (default "Resize panes"); height: a CSS length, default the host's height
 *     onChange({size, collapsed})   after the size or the collapse changes by the viewer or by the calls below (not on mount, not when a window resize forces a limit)
 *   split.a, split.b          the pane elements          split.el   the root
 *   split.size() -> percent of the first pane (0 to 100)     split.setSize(percent)     clamped to the limits (0 or 100 collapses a side that may)
 *   split.collapsed() -> "a" | "b" | null                    split.collapse("a" | "b")  only a side collapse allows
 *   split.restore()           back to the size before the collapse
 *   split.destroy()           remove listeners and the markup (the panes' content goes with it)
 * Keys on the divider (APG window splitter): the arrows across the divider move it (Left and Right, or Up and Down when stacked; mirrored in right-to-left text), Home and End go to the smallest and largest first pane, Enter collapses the first pane (the second when collapse is "b") or restores; an arrow pressed at a limit collapses a side that may collapse, and from a collapsed pane an arrow away from the edge restores. The double click is a pointer shortcut only: the keys reach every size.
 * The 7px of hit area either side of the divider covers the edge of a pane, scrollbar included. The host needs a width; stacked it also needs a height (or pass height). The collapsed pane is inert, so its content takes no focus.
 *
 * @id        kit.split-pane
 * @kind      component
 * @group     Kit
 * @status    new
 * @version   0.1.0
 * @updated   2026-11-22
 * @summary   Two panes and a resizable divider, side by side or stacked, nestable: drag or arrow keys, min and max, collapse and restore, double-click for the default, size remembered per viewer.
 * @tags      split pane, splitter, resize, divider, panes, layout, master detail, window splitter, collapse, keyboard, pointer, touch
 * @requires  none
 * @files     kit/split-pane.css, kit/samples/split-pane.json, kit/previews/split-pane.js
 * @provides  Kit.splitPane.mount
 * @config    Kit.splitPane.mount(el, opts) | a, b (nodes), orientation (horizontal or vertical), size (percent, default 50), min, max (percent, "240px" or [first, second]), collapse (both, a, b, none), step (percent), key (localStorage), label, height, onChange({size, collapsed})
 * @tokens    --panel --rule --ink-3 --accent --seam? --radius?
 * @globals   none
 * @db        none
 * @related   layout.explorer-shell, pattern.master-detail
 * @source    ADP extra kits | WAI-ARIA Authoring Practices, window splitter pattern | the keys, the separator and its aria-valuenow
 * @preview   {"render": "kit.split-pane", "samples": ["kit/samples/split-pane.json"]}
 */
(function () {
'use strict';
const Kit = window.Kit = window.Kit || { version: '0.1.0' };
let uid = 0;
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const el = (cls, tag = 'div') => { const e = document.createElement(tag); e.className = cls; return e; };
const pair = (v, d) => v == null ? [d, d] : Array.isArray(v) ? v : [v, v];

function mount(host, opts = {}) {
  const horiz = opts.orientation !== 'vertical', step = opts.step || 5, mode = opts.collapse || 'both';
  const can = { a: mode === 'both' || mode === 'a', b: mode === 'both' || mode === 'b' };
  const dflt = clamp(+(opts.size == null ? 50 : opts.size) || 50, 0, 100);
  const id = 'kit-sp-' + (++uid);
  const root = el('kit-sp kit-sp-' + (horiz ? 'h' : 'v')), pa = el('kit-sp-pane'), pb = el('kit-sp-pane'), bar = el('kit-sp-bar');
  const grip = el('kit-sp-grip', 'span');
  pa.id = id; grip.setAttribute('aria-hidden', 'true'); bar.append(grip);
  bar.setAttribute('role', 'separator'); bar.tabIndex = 0;
  bar.setAttribute('aria-orientation', horiz ? 'vertical' : 'horizontal');
  bar.setAttribute('aria-controls', id); bar.setAttribute('aria-label', opts.label || 'Resize panes');
  root.style.setProperty('--kit-sp-h', opts.height || '100%');   // set on every root so a nested split never inherits its parent's
  if (opts.a != null) pa.append(opts.a);
  if (opts.b != null) pb.append(opts.b);
  root.append(pa, bar, pb); host.append(root);

  let want = dflt, last = dflt, drag = null;       // want: the size the viewer chose; last: the size before a collapse
  if (opts.key) try { const [v, l] = String(localStorage.getItem(opts.key)).split('|').map(parseFloat); if (isFinite(v)) want = clamp(v, 0, 100); if (l > 0 && l < 100) last = l; } catch (_) {}

  const avail = () => { const r = root.getBoundingClientRect(), b = bar.getBoundingClientRect(); return (horiz ? r.width - b.width : r.height - b.height) || 1; };
  function limits() {
    const w = avail(), f = v => typeof v === 'string' && v.endsWith('px') ? parseFloat(v) / w * 100 : parseFloat(v);
    const [n0, n1] = pair(opts.min, 10).map(f), [x0, x1] = pair(opts.max, 100).map(f);
    let lo = Math.max(n0, 100 - x1), hi = Math.min(x0, 100 - n1);
    if (lo > hi) lo = hi = (lo + hi) / 2;
    return [lo, hi];
  }
  function place(raw, snap) {                       // snap: how far past a limit collapses (1 = the limit itself, .5 = half of it, 0 = only an exact 0 or 100)
    const [lo, hi] = limits();
    if (can.a && (raw <= 0 || raw < lo * snap)) return 0;
    if (can.b && (raw >= 100 || raw > 100 - (100 - hi) * snap)) return 100;
    return clamp(raw, lo, hi);
  }
  const side = p => p <= 0 && can.a ? 'a' : p >= 100 && can.b ? 'b' : null;
  const eff = () => place(want, 0);               // a size the window can no longer hold is clamped, never collapsed

  function render() {
    const p = eff(), [lo, hi] = limits(), c = side(p);
    root.style[horiz ? 'gridTemplateColumns' : 'gridTemplateRows'] = `minmax(0, ${p}fr) auto minmax(0, ${100 - p}fr)`;
    pa.inert = c === 'a'; pb.inert = c === 'b'; bar.dataset.c = c || '';
    bar.setAttribute('aria-valuenow', Math.round(p));
    bar.setAttribute('aria-valuemin', can.a ? 0 : Math.round(lo));
    bar.setAttribute('aria-valuemax', can.b ? 100 : Math.round(hi));
    return c;
  }
  function save() { if (opts.key) try { localStorage.setItem(opts.key, want + '|' + last); } catch (_) {} }
  function set(raw, snap = 0) {
    const p = place(raw, snap), was = eff();
    want = p; if (!side(p)) last = p;
    const c = render();
    if (!drag) save();
    if (p !== was && opts.onChange) opts.onChange({ size: api.size(), collapsed: c });
  }

  const off = [];
  const on = (t, ty, f) => { t.addEventListener(ty, f); off.push(() => t.removeEventListener(ty, f)); };
  const at = e => horiz ? e.clientX : e.clientY;
  const rtl = () => horiz && getComputedStyle(root).direction === 'rtl';
  on(bar, 'pointerdown', e => {
    if (e.button > 0) return;
    drag = { x: at(e), p: eff(), w: avail(), s: rtl() ? -1 : 1 };
    try { bar.setPointerCapture(e.pointerId); } catch (_) {}
    root.classList.add('kit-sp-drag');
  });
  on(bar, 'pointermove', e => { if (drag) set(drag.p + (at(e) - drag.x) * drag.s / drag.w * 100, .5); });
  const end = () => { if (drag) save(); drag = null; root.classList.remove('kit-sp-drag'); };
  on(bar, 'pointerup', end); on(bar, 'pointercancel', end);
  on(bar, 'dblclick', () => set(dflt));
  on(bar, 'keydown', e => {
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    const p = eff(), c = side(p), [lo, hi] = limits();
    const grow = horiz ? (rtl() ? 'ArrowLeft' : 'ArrowRight') : 'ArrowDown', shrink = horiz ? (rtl() ? 'ArrowRight' : 'ArrowLeft') : 'ArrowUp';
    const nudge = d => { const r = p + d; set(d < 0 && p > lo && r < lo ? lo : d > 0 && p < hi && r > hi ? hi : r, 1); };   // reach the limit before collapsing past it
    if (e.key === grow) { if (c === 'a') set(last); else if (!c) nudge(step); }
    else if (e.key === shrink) { if (c === 'b') set(last); else if (!c) nudge(-step); }
    else if (e.key === 'Home') set(lo);
    else if (e.key === 'End') set(hi);
    else if (e.key === 'Enter') c ? set(last) : set(can.a ? 0 : can.b ? 100 : p);
    else return;
    e.preventDefault();
  });
  const ro = window.ResizeObserver ? new ResizeObserver(render) : null;
  if (ro) ro.observe(root); else { on(window, 'resize', render); }
  render();

  const api = {
    a: pa, b: pb, el: root,
    size: () => Math.round(eff() * 10) / 10,
    setSize: v => set(+v),
    collapsed: () => side(eff()),
    collapse: s => set(s === 'b' ? 100 : 0),
    restore: () => set(last),
    destroy() { off.forEach(f => f()); if (ro) ro.disconnect(); root.remove(); },
  };
  return api;
}

Kit.splitPane = Object.freeze({ mount });
})();
